={{
(() => {
  let allScenes = [];
  try { allScenes = $('Merge Hybrid Scenes').all(); } catch(e) {}
  if (!allScenes || allScenes.length === 0) {
    try { allScenes = $('Inject Saved 5 Scenes (Exec 35)').all(); } catch(e) {}
  }
  if (!allScenes || allScenes.length === 0) {
    allScenes = $input.all();
  }

  const scenes = allScenes.sort((a, b) => (a.json?.sceneNumber || 0) - (b.json?.sceneNumber || 0));

  // Dual audio URLs from CloudConvert
  const ccTasks = $('Convert Dual Voice to Pure MP3 (CloudConvert)').first().json.data?.tasks || [];
  const part1File = ccTasks.find(t => t.name === 'export-part1')?.result?.files?.[0]?.url;
  const part2File = ccTasks.find(t => t.name === 'export-part2')?.result?.files?.[0]?.url;

  const d1 = $('Poll Voiceover Part 1').first().json.movie?.duration || 33.32;
  const d2 = $('Poll Voiceover Part 2').first().json.movie?.duration || 27.20;

  // 5 Visuals (15s each = 75s total)
  const visuals = scenes.map((s, idx) => {
    const v = {
      type: 'VIDEO',
      id: 'scene' + (idx + 1),
      src: s.json.url || s.json.videoUrl,
      resize: 'cover',
      volume: 0,
      enterBegin: idx * 15,
      exitEnd: (idx + 1) * 15
    };
    if (idx < 4) {
      v.transition = 'fade';
      v.transitionDuration = 0.5;
      v.transitionId = 'scene' + (idx + 2);
    }
    return v;
  });

  const audios = [
    {
      src: part1File,
      volume: 1.0,
      enter: 0,
      exit: d1
    },
    {
      src: part2File,
      volume: 1.0,
      enter: d1,
      exit: d1 + d2
    },
    {
      src: 'https://ia600908.us.archive.org/35/items/tolsetmusic-house-of-fear-mystical-cinematic-background-music-542082/tolsetmusic-house-of-fear-mystical-cinematic-background-music-542082.mp3',
      volume: 0.15,
      enter: 0,
      exit: 75
    }
  ];

  const captions = scenes.map((s, idx) => ({
    start: idx * 15,
    end: (idx + 1) * 15,
    text: s.json.voiceoverText || ''
  }));

  const payload = {
    name: 'world-mysteries-75s',
    duration: 75,
    resolution: 'youtube-short',
    frameRate: 30,
    backgroundColor: '#000000',
    outputFormat: 'mp4',
    visuals: visuals,
    audios: audios,
    subtitle: {
      captions: captions,
      animation: 'pop',
      activeWord: {
        color: '#000000',
        background: '#FFE600'
      },
      font: {
        family: 'Noto Sans Devanagari',
        size: 58,
        color: '#FFFFFF',
        bold: true
      },
      stroke: {
        color: '#000000',
        width: 8
      },
      position: 'bottom-center',
      maxWordsPerLine: 3
    }
  };

  return JSON.stringify({ payload });
})()
}}

={{
(() => {
  let allScenes = [];
  try { allScenes = $('Merge Hybrid Scenes').all(); } catch(e) {}
  if (!allScenes || allScenes.length === 0) {
    try { allScenes = $('Inject Saved 5 Scenes (Exec 35)').all(); } catch(e) {}
  }
  if (!allScenes || allScenes.length === 0) {
    allScenes = $input.all();
  }

  const batchScenes = allScenes
    .sort((a, b) => (a.json?.sceneNumber || 0) - (b.json?.sceneNumber || 0))
    .slice(3, 5)
    .map((s) => {
      let voiceElId = 'pNInz6obpgDQGcFmaJgB';
      let speed = 1.20;
      try {
        const site = $('Filter: My Chat Only').first().json || {};
        voiceElId = site.elevenLabsVoiceId || voiceElId;
        speed = site.voiceSpeed || speed;
      } catch(e) {}
      return {
        elements: [
          {
            type: 'voice',
            voice: voiceElId,
            text: s.json.voiceoverText || '',
            model: 'elevenlabs',
            speed: speed
          }
        ]
      };
    });

  return JSON.stringify({
    resolution: 'preview',
    quality: 'low',
    scenes: batchScenes
  });
})()
}}
